def build():
    checkpoint={'schema_version':1,'status':'partial_explicit_second_batch','tracks':{}}
    all_ids=set()
    for tool,text in SPECS.items():
        seed=json.loads((ROOT/'tools'/'curriculum.json').read_text(encoding='utf-8'))
        first=json.loads((BANK/f'{tool}.json').read_text(encoding='utf-8'))
        all_ids.update(p['id'] for p in seed['problems'])
        all_ids.update(p['id'] for p in first)
        rows=[line.split('|') for line in text.strip().splitlines()]
        assert all(len(row)==7 for row in rows),tool
        rows.sort(key=lambda row:int(row[0]))
        assert len({row[1] for row in rows})==len(rows)
        prefix={'delta-lake':'DELTA-LAKE'}.get(tool,tool.upper())
        path=BANK/f'{tool}-batch2.json'
        prior=json.loads(path.read_text(encoding='utf-8')) if path.exists() else []
        prior_by_title={p['title']:p for p in prior}
        assert set(prior_by_title)<={row[1] for row in rows},f'{tool}: refusing title deletion'
        next_number=max([int(p['id'].rsplit('-',1)[1]) for p in prior]+[START[tool]-1])+1
        problems=[]
        by_level={}
        for level,title,task,fixture,result,boundary,hint in rows:
            level=int(level)
            old=prior_by_title.get(title)
            if old:pid=old['id']
            else:
                pid=f'RLP-{prefix}-{next_number:03}'
                next_number+=1
            candidates=[p for p in first if p['level']<=level]
            previous=by_level.get(level) or candidates[-1]['id']
            by_level[level]=pid
            assert previous in all_ids, (pid,previous)
            hints=hints_for(tool,title,result)
            hints[2]=hint
            problem={'id':pid,'tool_id':tool,'title':title,'level':level,'prerequisites':old['prerequisites'] if old else [previous],
                'scenario':task,'task':task,'learning_objective':title,
                'inputs':{'fixture':fixture,'environment':'Existing compatible local or authorized training environment; record actual runtime/service capabilities. Cloud access unavailable means environment_blocked, not execution acceptance.'},
                'expected_output':{'observed_behavior':result},
                'constraints':['Use only supplied small synthetic fixtures and isolated learner-owned outputs; preserve source data and previous accepted batches.',
                               'Use existing authorized cloud resources only; do not provision paid resources, expose credentials, mutate production data or send actual notifications to people.',
                               'Report unsupported runtime features as environment_blocked; a design or local simulation alone does not establish cloud execution.'],
                'acceptance_criteria':[result,'Demonstrate the additional boundary: '+boundary,
                                       'Submit implementation/configuration and actual observed output with assistance disclosure; reviewer checks correctness before verified completion.'],
                'estimated_minutes':10 if level<2 else 20 if level<4 else 35 if level<6 else 50 if level<9 else 90,
                'engineering_relevance':f'{title} supports a specific ingestion, storage, transformation or operational contract. After verification, explain which downstream consumer depends on this behavior and one limitation.',
                'official_docs':[DOCS[tool],EXTRA_DOCS[tool]],'verification':{'kind':'artifact_review'},'topic_id':None,'published_version':'2026.10.26.2',
                'independent_prerequisites':[],'difficulty':f'level_{level}',
                'challenge_kind':'transfer' if level==10 else 'bridge' if len([p for p in problems if p['level']==level])==0 else 'initial',
                'skill_prerequisites':[] if level==0 else ['Verified preceding problem evidence or a reviewer-approved diagnostic covering its exact prerequisite contract.'],
                'progressive_hints':hints,'sequence':int(pid.rsplit('-',1)[1]),'authoring_batch':'cloud-explicit-002',
                'followup':{'task':'Independently reconstruct this bounded task using the changed-input check. Explain and demonstrate the result without the earlier implementation open.',
                            'inputs':{'base_fixture':fixture,'changed_input_check':boundary},'expected_output':{'contract':boundary},
                            'verification':{'kind':'artifact_review'},'constraints':['No solution reveal; disclose assistance and retain actual observed evidence.']}}
            assert len(set(hints))==3
            problems.append(problem)
            all_ids.add(pid)
        assert len({p['task'] for p in problems})==len(problems)
        assert not ({p['id'] for p in problems}&{p['id'] for p in first})
        assert not ({p['task'] for p in problems}&{p['task'] for p in first})
        path.write_text(json.dumps(problems,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
        checkpoint['tracks'][tool]={'target':TARGETS[tool],'preserved_first_additions':len(first),'batch2_additions':len(problems),
             'prepared_total_including_seed':1+len(first)+len(problems),'remaining':TARGETS[tool]-1-len(first)-len(problems),
             'next_id':f'RLP-{prefix}-{next_number:03}','next_action':'Author a distinct concrete capability fixture; do not pad to the target with mechanically varied modes.'}
    (BANK/'authors'/'cloud-batch2-checkpoint.json').write_text(json.dumps(checkpoint,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(checkpoint,indent=2))

if __name__=='__main__':build()
